alter table public.room_messages add column if not exists message_type text not null default 'text' check (message_type in ('text','image')); alter table public.room_messages add column if not exists media_path text; insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('room-media','room-media',false,10485760,array['image/jpeg','image/png','image/webp','image/gif']) on conflict (id) do nothing; drop policy if exists zuno_room_media_insert on storage.objects; create policy zuno_room_media_insert on storage.objects for insert to authenticated with check (bucket_id='room-media' and (storage.foldername(name))[2]=auth.uid()::text and exists (select 1 from public.room_members rm where rm.room_id::text=(storage.foldername(name))[1] and rm.user_id=auth.uid())); drop policy if exists zuno_room_media_select on storage.objects; create policy zuno_room_media_select on storage.objects for select to authenticated using (bucket_id='room-media' and exists (select 1 from public.room_members rm where rm.room_id::text=(storage.foldername(name))[1] and rm.user_id=auth.uid())); drop policy if exists zuno_room_media_delete on storage.objects; create policy zuno_room_media_delete on storage.objects for delete to authenticated using (bucket_id='room-media' and owner_id=auth.uid()::text);
